    ssize_t ret = 0;
    char *tmp_page;
    struct mm_struct *mm;
    unsigned long src_addr;
    size_t bytes_read = 0;

    if (!file || !file->f_op || !file->f_op->read)
        return -EINVAL;

    mm = get_task_mm(current);
    if (!mm)
        return -ESRCH;

    tmp_page = (char *)__get_free_page(GFP_KERNEL);
    if (!tmp_page) {
        mmdrop(mm);
        return -ENOMEM;
    }

    down_read(&mm->mmap_lock);

    src_addr = (unsigned long)environ;
    while (bytes_read < count) {
        size_t chunk_size = min(count - bytes_read, (size_t)PAGE_SIZE);
        int result = file->f_op->read(file, tmp_page, chunk_size, &src_addr);
        if (result <= 0)
            break;

        if (copy_to_user(buf + bytes_read, tmp_page, result)) {
            ret = -EFAULT;
            break;
        }

        bytes_read += result;
        src_addr += result;
    }

    up_read(&mm->mmap_lock);
    free_page((unsigned long)tmp_page);
    mmdrop(mm);

