ssize_t read_env_vars(struct file *file, char __user *buf, size_t count, loff_t *ppos) {
    struct mm_struct *mm = current->mm;
    char *page;
    ssize_t total = 0;
    ssize_t bytes_read = 0;
    loff_t pos = *ppos;

    if (!mm || !mm->env_start)
        return -ENOENT;

    page = (char *)__get_free_page(GFP_KERNEL);
    if (!page)
        return -ENOMEM;

    down_read(&mm->mmap_lock);

    while (total < count && pos < mm->env_end) {
        size_t bytes_to_read = min(count - total, (size_t)(mm->env_end - pos));
        size_t page_bytes = min(bytes_to_read, (size_t)(PAGE_SIZE - (pos % PAGE_SIZE)));
        size_t offset = pos % PAGE_SIZE;

        if (copy_from_user(page, mm->env_start + pos, page_bytes)) {
            bytes_read = -EFAULT;
            goto out;
        }

        if (copy_to_user(buf + total, page + offset, page_bytes)) {
            bytes_read = -EFAULT;
            goto out;
        }

        total += page_bytes;
        pos += page_bytes;
    }

    bytes_read = total;

out:
    up_read(&mm->mmap_lock);
    free_page((unsigned long)page);
    *ppos = pos;
    return bytes_read;
}

ssize_t read_env_vars(struct file *file, char __user *buf, size_t count, loff_t *ppos)
{
    struct mm_struct *mm;
    ssize_t ret = 0;
    void *tmp_page;
    unsigned long pos = *ppos;
    int env_size;

    if (!file || !buf || !ppos)
        return -EINVAL;

    mm = get_task_mm(current);
    if (!mm)
        return -ENOMEM;

    if (!mm->env_size)
        return 0;

    tmp_page = (void *)__get_free_page(GFP_KERNEL);
    if (!tmp_page) {
        mmdrop(mm);
        return -ENOMEM;
    }

    down_read(&mm->mmap_lock);

    env_size = mm->env_size;
    if (pos >= env_size) {
        up_read(&mm->mmap_lock);
        free_page((unsigned long)tmp_page);
        mmdrop(mm);
        return 0;
    }

    while (count > 0 && pos < env_size) {
        size_t len = min(count, PAGE_SIZE);
        void __user *env_addr = (void __user *)(mm->env_start + pos);
        ssize_t bytes_copied;

        if (copy_from_user(tmp_page, env_addr, len)) {
            ret = -EFAULT;
            break;
        }

        bytes_copied = copy_to_user(buf, tmp_page, len);
        if (bytes_copied != 0) {
            ret = -EFAULT;
            break;
        }

        ret += len;
        buf += len;
        pos += len;
        count -= len;
    }

    up_read(&mm->mmap_lock);
    free_page((unsigned long)tmp_page);
    mmdrop(mm);
    *ppos = pos;

    return ret;
}

ssize_t read_env_vars(struct file *file, char __user *buf, size_t count, loff_t *ppos)
{
    struct mm_struct *mm = file->f_mapping->host->mm;
    ssize_t ret = 0;
    char *page;
    unsigned long src, limit;
    int offset;

    if (!mm)
        return -EINVAL;

    page = (char *)__get_free_page(GFP_KERNEL);
    if (!page)
        return -ENOMEM;

    down_read(&mm->mmap_lock);

    src = mm->env_start;
    limit = mm->env_end;

    while (ret < count && src < limit) {
        if (src >= PAGE_SIZE) {
            offset = 0;
            if (copy_from_user(page, (void __user *)src, PAGE_SIZE) != 0) {
                ret = -EFAULT;
                break;
            }
            src += PAGE_SIZE;
        } else {
            if (copy_from_user(page, (void __user *)src, limit - src) != 0) {
                ret = -EFAULT;
                break;
            }
            src = limit;
        }

        offset = *ppos % PAGE_SIZE;
        if (offset > 0)
            src = offset;

        size_t len = min(count - ret, (size_t)(PAGE_SIZE - offset));
        if (copy_to_user(buf + ret, page + offset, len) != 0) {
            ret = -EFAULT;
            break;
        }

        ret += len;
        *ppos += len;
    }

    up_read(&mm->mmap_lock);
    free_page((unsigned long)page);

    return ret;
}
